# Issue #121 (S314): with no usable age, getPedMaxAge() must return NA quietly
# instead of max()'s "no non-missing arguments" warning and -Inf. Its caller,
# getPyramidPlot(), already guards is.na(maxAge), so the warning was pure noise.
test_that("getPedMaxAge returns NA without warning when the age column is absent", {
  noAge <- data.frame(
    id = c("A", "B"), sex = c("M", "F"), stringsAsFactors = FALSE
  )
  expect_no_warning(res <- getPedMaxAge(noAge))
  expect_true(is.na(res))
})

test_that("getPedMaxAge returns NA without warning when every age is NA", {
  allNa <- data.frame(
    id = c("A", "B"), sex = c("M", "F"), age = NA_real_,
    stringsAsFactors = FALSE
  )
  expect_no_warning(res <- getPedMaxAge(allNa))
  expect_true(is.na(res))
})

test_that("getPedMaxAge returns NA without warning for a zero-row pedigree", {
  zeroRow <- data.frame(
    id = character(0L), sex = character(0L), age = numeric(0L),
    stringsAsFactors = FALSE
  )
  expect_no_warning(res <- getPedMaxAge(zeroRow))
  expect_true(is.na(res))
})

