  # 0.9 also draws checkKinshipOverrides()'s D6 heads-up (off-diagonal > 0.5).
  # Capture it so it is asserted rather than leaking as an unasserted warning
  # (issue #121). Presence only: the heads-up currently fires twice per call
  # (prepareKinshipOverrides + applyKinshipOverrides both validate); that
  # duplication is a separate follow-up, so the count is deliberately not pinned.
  warns <- character(0L)
  withCallingHandlers(
    expect_error(
      suppressMessages(gvaConvergence(fx$ped,
        pop = fx$pop, nMax = 800L, seed = 11L, kinshipOverrides = badVal
      )),
      "above the maximum"
    ),
    warning = function(w) {
      warns <<- c(warns, conditionMessage(w))
      invokeRestart("muffleWarning")
    }
  )
  expect_true(any(grepl("valid only for inbred pairs", warns)))
})

